/* fr_cal.h — the fault-reaction shadow's calibration copies (app/fr_cal.c,
 * GENERATED by tools/gen_fr_cal.py; byte-checked against the stock image by
 * tests/unit/test_fr_shadow.c --cal). Read-only like the shadow: an output
 * path may not include it. */
#ifndef TCU_APP_FR_CAL_H
#define TCU_APP_FR_CAL_H

#if defined(TCU_OUTPUT_PATH)
#error "the fault-reaction shadow is read-only: an output path may not include fr_cal.h"
#endif

#include <stdint.h>

#define FR_NG 195u              /* DSM groups 1..195 */
#define FR_NE 53u               /* comm-monitor entries 0..52 */
#define FR_CAL_NCHK 292u        /* the scalar byte checks (gen_fr_cal.py prints the count) */

/* 0x642BC → the comm monitor's scalars */
typedef struct {
    uint16_t sup_min, sup_max;  /* 0x195EBE / C0: 9000 / 17000 mV */
    uint16_t thr_u0001;         /* 0x195EC2: 50 */
    uint16_t thr_u11e4;         /* 0x195EC4: 50 */
    uint16_t thr_u0074;         /* 0x195EC6: 50 */
    uint16_t thr_137;           /* 0x195EC8: 50 */
    uint8_t  mask_u0001;        /* 0x195D76: 1 */
    uint8_t  mask_u0074;        /* 0x195D77: 1 */
    uint8_t  b2en;              /* 0x195D78: 0 */
} fr_cal_comm_t;

/* one RX message behind a comm entry */
typedef struct {
    uint16_t id;
    uint8_t  bus;               /* 1 / 2 (the stock's numbering: CAN_BUS1 / CAN_BUS2) */
    uint8_t  dlc;               /* the object's DLC (received >= it) */
    uint16_t to;                /* timeout, x 10 ms passes */
    uint8_t  en;                /* the coding byte: 0x3B / 0x23 / 0x00 */
    uint8_t  crc, ctr;          /* a CRC / counter check exists */
    uint8_t  tol_crc, tol_ctr, tol_dlc;
    uint8_t  hdl;               /* the ROM handle */
    uint32_t st;                /* the status byte 0xFFF8400C + 0x10 k (witness only) */
    uint32_t obj;               /* the ROM object (the byte check) */
    uint32_t en_a;              /* the coding byte's cal address */
} fr_cal_rx_t;

/* 0x64450 → 0x13A9D4 / 0x13A616: w[0] delay +0x10 (20), w[1] stop latch +0x14
 * (20), w[2..7] the output limits (gears 1..6), w[8..13] the vehicle limits,
 * w[14..19] the engine limits, w[20..25] the EF12 limits; b[] the rescale
 * flags +0x68..+0x7C; x80 the +0x48 source; sub0 / sub1 the object's
 * subscription words (RAM, the driving dump) */
typedef struct {
    uint16_t w[26];
    uint8_t  b[6];
    uint16_t x80;
    uint32_t sub0, sub1;
} fr_cal_13a_t;

typedef struct {
    uint32_t addr;
    uint8_t  width;             /* 1 / 2 */
    uint16_t val;
} fr_cal_chk_t;

extern const uint8_t       fr_cal_grp[FR_NG][36];     /* 0x1923EC */
extern const uint16_t      fr_cal_dep[FR_NG][3];      /* 0x1955A8 */
extern const fr_cal_comm_t fr_cal_comm;
extern const uint16_t      fr_cal_reload[FR_NE];      /* 0x191B30 */
extern const uint16_t      fr_cal_thr[FR_NE];         /* 0x191BB4 */
extern const uint8_t       fr_cal_mask[FR_NE];        /* 0x191C38 */
extern const uint8_t       fr_cal_ent[FR_NE][3];      /* RAM 0xFFF85289 (dump) */
extern const uint8_t       fr_cal_slot_grp[13];       /* its slot -> group map */
extern const fr_cal_rx_t   fr_cal_rx[FR_NE];
extern const uint8_t       fr_cal_ctr_step;           /* 0x1918FE */
extern const fr_cal_13a_t  fr_cal_13a;
extern const uint32_t      fr_cal_13a_ptr[33];
extern const uint16_t      fr_cal_14e_reload;         /* 0x195FCA */
extern const uint8_t       fr_cal_6344e[54];          /* 0x6344E */
extern const fr_cal_chk_t  fr_cal_chk[FR_CAL_NCHK];

/* the group config fields (C = fr_cal_grp[g - 1], big-endian) */
#define FRC_U16(c, o) ((uint16_t)(((uint16_t)(c)[o] << 8) | (c)[(o) + 1]))
#define FRC_U32(c, o) (((uint32_t)(c)[o] << 24) | ((uint32_t)(c)[(o) + 1] << 16) | \
                       ((uint32_t)(c)[(o) + 2] << 8) | (uint32_t)(c)[(o) + 3])
#define FRC_FLAGS(c)  FRC_U16(c, 0x00)
#define FRC_FAIL(c)   FRC_U16(c, 0x02)
#define FRC_HEAL(c)   FRC_U16(c, 0x04)
#define FRC_R0(c)     FRC_U32(c, 0x08)
#define FRC_R1(c)     FRC_U32(c, 0x0C)
#define FRC_PTHR(c)   FRC_U16(c, 0x12)
#define FRC_P0(c)     FRC_U32(c, 0x14)
#define FRC_P1(c)     FRC_U32(c, 0x18)
#define FRC_RULE(c)   FRC_U16(c, 0x1C)
#define FRC_E20(c)    ((c)[0x20])
#define FRC_E21(c)    ((c)[0x21])
#define FRC_OPC(c)    FRC_U16(c, 0x22)

#endif /* TCU_APP_FR_CAL_H */
